// Maps an AutomationProject tag (src/data/automation-projects.ts) to its logo
// slug under /public/tech/<slug>.svg. Only brand/tool tags are listed; concept
// tags (Workflows, Funnels, SMS Automation, Custom Fields, …) are intentionally
// omitted so they render as plain text chips. GoHighLevel is resolved via
// SKILL_TO_IMAGE in automationToolIcon() below.
//
// Slugs marked "sourced" are full-color logos that are NOT in the
// tech-stack-icons package and so are not produced by
// scripts/extract-tech-icons.mjs — they were downloaded once into /public/tech.
// See the README "Tech icons" section.
export const AUTOMATION_TOOL_TO_ICON: Record<string, string> = {
  Slack: "slack",
  Zapier: "zapier",
  n8n: "n8n",
  OpenAI: "openai",
  Trello: "trello",
  Airtable: "airtable",
  Asana: "asana",
  Javascript: "js",
  "Gemini 2.5 Flash": "gemini",
  VAPI: "vapi",
  // sourced full-color SVGs (not from tech-stack-icons)
  Gmail: "gmail",
  "Google Sheets": "googlesheets",
  "Google Calendar": "googlecalendar",
  "Google Drive": "googledrive",
  Shopify: "shopify",
};

// Logos drawn only in near-black (brightest fill under ~5% luminance) or, for
// AWS, with dark text. They vanish on the dark theme, so <TechIcon> inverts
// them there (with a 180° hue-rotate, which keeps their hue).
const DARK_ON_DARK = new Set([
  "anthropic",
  "aws",
  "betterauth",
  "tanstack",
  "cursor",
  "expressjs",
  "framer",
  "github",
  "langchain",
  "mysql",
  "nextjs",
  "ollama",
  "openai",
  "posthog",
  "prisma",
  "railway",
  "shadcnui",
  "vercel",
]);

export interface TechIconSource {
  src: string;
  /** Invert in dark mode (dark-only logo). */
  invertOnDark: boolean;
}

function fromSlug(slug: string): TechIconSource {
  return { src: `/tech/${slug}.svg`, invertOnDark: DARK_ON_DARK.has(slug) };
}

// Resolve any logo path (e.g. a certification's logoUrl). Paths under
// /tech/ get the same dark-mode handling as skill icons.
export function logoSource(path: string): TechIconSource {
  const slug = path.match(/^\/tech\/(.+)\.svg$/)?.[1];
  return slug ? fromSlug(slug) : { src: path, invertOnDark: false };
}

// Resolve a skill label (DATA.skills) to its logo, or null if it has none.
export function skillIcon(skill: string): TechIconSource | null {
  const slug = SKILL_TO_ICON[skill];
  if (slug) return fromSlug(slug);
  const image = SKILL_TO_IMAGE[skill];
  if (image) return { src: image, invertOnDark: false };
  return null;
}

// Resolve an automation tag to its logo. Returns null for concept tags that
// have no logo (Workflows, Funnels, …), so callers fall back to text.
export function automationToolIcon(tag: string): TechIconSource | null {
  const slug = AUTOMATION_TOOL_TO_ICON[tag];
  if (slug) return fromSlug(slug);
  const image = SKILL_TO_IMAGE[tag]; // GoHighLevel
  if (image) return { src: image, invertOnDark: false };
  return null;
}
